-- Evidence of every successful user creation: who created whom, and how.
-- Failed attempts are not stored here: they belong to the security logs, because a rolled-back
-- creation must leave no row behind.
CREATE TABLE auth_schema.user_creation_audit (
  -- generated by Auth, like service_token.token_id: no default, so a row cannot invent its own id
  audit_id           uuid        NOT NULL,
  operation          text        NOT NULL,
  actor_kind         text        NOT NULL,
  -- the ADMIN who registered the user; null when an operator initialized the environment
  actor_user_id      uuid,
  -- the deployment identity of the operator; null when an ADMIN registered the user
  operator_identity  text,
  created_user_id    uuid        NOT NULL,
  outcome            text        NOT NULL,
  occurred_at        timestamptz NOT NULL,
  correlation_id     text        NOT NULL,
  CONSTRAINT pk_user_creation_audit PRIMARY KEY (audit_id),
  -- one record per user: the attribution of a user is never ambiguous
  CONSTRAINT uq_user_creation_audit_created_user UNIQUE (created_user_id),
  CONSTRAINT chk_user_creation_audit_operation
    CHECK (operation IN ('USER_REGISTERED', 'INITIAL_ADMIN_CREATED')),
  CONSTRAINT chk_user_creation_audit_actor_kind
    CHECK (actor_kind IN ('ADMIN', 'OPERATOR')),
  -- each operation has exactly one valid actor; the ADMIN role of the actor is checked by the
  -- use case at creation time, so a later change of that user's role never invalidates a record
  CONSTRAINT chk_user_creation_audit_actor CHECK (
    (operation <> 'USER_REGISTERED'
      OR (actor_kind = 'ADMIN' AND actor_user_id IS NOT NULL AND operator_identity IS NULL))
    AND (operation <> 'INITIAL_ADMIN_CREATED'
      OR (actor_kind = 'OPERATOR' AND operator_identity IS NOT NULL AND actor_user_id IS NULL))
  ),
  CONSTRAINT chk_user_creation_audit_outcome CHECK (outcome = 'SUCCESS'),
  CONSTRAINT chk_user_creation_audit_operator_identity
    CHECK (operator_identity IS NULL OR char_length(operator_identity) BETWEEN 1 AND 200),
  CONSTRAINT chk_user_creation_audit_correlation_id CHECK (char_length(correlation_id) >= 1)
);
